insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('administrativo-acervo-fundamentos-organizacao','Fundamentos e organização','Fundamentos e organização administrativa','500','Direito Administrativo — fundamentos, organização e agentes públicos','Regime jurídico, fontes, administração direta e indireta, órgãos, centralização, descentralização, concentração, desconcentração e agentes públicos.','## Conteúdo atualizado

Estude fontes, regime jurídico-administrativo, princípios da supremacia do interesse público e indisponibilidade do interesse público, sempre em diálogo com a Constituição.

A Administração Direta integra a estrutura dos entes federativos. A Administração Indireta é formada por autarquias, fundações públicas, empresas públicas e sociedades de economia mista. **Desconcentração** distribui competências dentro da mesma pessoa jurídica; **descentralização** transfere a execução para outra pessoa, por outorga ou delegação.

Órgão público não tem personalidade jurídica própria. Agentes públicos abrangem servidores, empregados públicos, temporários, particulares em colaboração e agentes políticos. Diferencie cargo, emprego e função.

> **Atualização:** este resumo foi reorganizado a partir dos PDFs enviados e confrontado com a Constituição e a legislação vigente.','Concursos públicos — Direito Administrativo','500','Conteúdo consolidado dos PDFs enviados pelo usuário em 28/10/2026, com revisão de vigência e remoção de marcas autorais.','[{"title": "Material enviado pelo usuário — 01-01_AlfaCon--introducao-ramos-do-direito-fontes-regime-juridico-administrativo-principios-da-indisponibilidade-e-supremacia-co.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 01-02_AlfaCon--administracao-direta-e-indireta.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 01-03_AlfaCon--administracao-direta-e-indireta_2.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 01-04_AlfaCon--orgaos-publicos.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 01-05_AlfaCon--centralizacao-descentralizacao-concentracao-e-desconcentracao.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 02-01_AlfaCon--agentes-publicos.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 02-02_AlfaCon--agentes-publicos-parte-2.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]','[{"f": "Qual é o ponto de atualização desta trilha?", "b": "Regime jurídico, fontes, administração direta e indireta, órgãos, centralização, descentralização, concentração, desconcentração e agentes públicos."}]','[{"q": "O conteúdo desta trilha foi organizado a partir dos materiais enviados e revisado para a legislação vigente.", "a": true, "why": "A trilha recebeu revisão editorial e jurídica."}]','active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('administrativo-acervo-poderes','Direito Administrativo','Poderes administrativos','501','Direito Administrativo — poderes administrativos','Poder vinculado e discricionário, hierárquico, disciplinar, regulamentar e poder de polícia.','## Conteúdo atualizado

Poder vinculado deixa menor espaço de escolha quando a lei fixa os requisitos. Poder discricionário permite juízo de conveniência e oportunidade dentro dos limites legais; não autoriza arbitrariedade.

O poder hierárquico organiza e distribui funções; o disciplinar apura infrações e aplica sanções a servidores e particulares sujeitos a vínculo especial; o regulamentar edita atos normativos para fiel execução da lei. Poder de polícia limita ou condiciona direitos e atividades em benefício do interesse coletivo, com competência, finalidade, forma, proporcionalidade e devido processo.

> **Cai em prova:** mérito administrativo não se confunde com legalidade; o Judiciário controla legalidade e abusos, sem substituir a Administração na conveniência legítima.','Concursos públicos — Direito Administrativo','501','Conteúdo consolidado dos PDFs enviados pelo usuário em 28/10/2026, com revisão de vigência e remoção de marcas autorais.','[{"title": "Material enviado pelo usuário — 02-03_AlfaCon--poderes-administrativos.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]','[{"f": "Qual é o ponto de atualização desta trilha?", "b": "Poder vinculado e discricionário, hierárquico, disciplinar, regulamentar e poder de polícia."}]','[{"q": "O conteúdo desta trilha foi organizado a partir dos materiais enviados e revisado para a legislação vigente.", "a": true, "why": "A trilha recebeu revisão editorial e jurídica."}]','active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('administrativo-acervo-controle','Direito Administrativo','Controle da Administração','502','Direito Administrativo — controle da Administração Pública','Controle interno, externo, legislativo, judicial, social, prévio, concomitante, posterior, hierárquico e finalístico; anulação e revogação.','## Conteúdo atualizado

Controle interno é exercido dentro do próprio Poder ou órgão; controle externo é exercido pelo Legislativo com auxílio dos Tribunais de Contas, sem excluir o controle judicial. Controle prévio ocorre antes do ato, concomitante durante sua execução e posterior depois dos resultados.

A **anulação** retira ato ilegal, com efeitos retroativos em regra e respeito à proteção da confiança quando cabível. A **revogação** retira ato válido por conveniência e oportunidade, com efeitos prospectivos; não cabe para atos vinculados ou já consumados. A Administração deve motivar decisões e respeitar contraditório e ampla defesa quando houver sanção ou restrição de direitos.

> **Cai em prova:** revogação trata de mérito; anulação trata de ilegalidade.','Concursos públicos — Direito Administrativo','502','Conteúdo consolidado dos PDFs enviados pelo usuário em 28/10/2026, com revisão de vigência e remoção de marcas autorais.','[{"title": "Material enviado pelo usuário — 03-01_AlfaCon--controle-da-administracao-publica-introducao-e-conceito-classificacoes-quanto-a-origem-controle-interno-controle-.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 03-02_AlfaCon--controle-da-administracao-publica-classificacoes-quanto-ao-momento-de-exercicio-controle-previo-controle-concomit.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 03-03_AlfaCon--controle-da-administracao-publica-classificacoes-quanto-a-amplitude-controle-hierarquico-controle-finalistico-esp.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 03-04_AlfaCon--controle-da-administracao-publica-especies-de-controle-controle-legislativo-controle-judicial-exercicios-de-contr.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 03-05_AlfaCon--controle-da-administracao-publica-anulacao-e-revogacao-exercicios-de-controle-da-administracao-publica.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]','[{"f": "Qual é o ponto de atualização desta trilha?", "b": "Controle interno, externo, legislativo, judicial, social, prévio, concomitante, posterior, hierárquico e finalístico; anulação e revogação."}]','[{"q": "O conteúdo desta trilha foi organizado a partir dos materiais enviados e revisado para a legislação vigente.", "a": true, "why": "A trilha recebeu revisão editorial e jurídica."}]','active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('administrativo-acervo-licitacoes-14133','Direito Administrativo','Licitações e Lei 14.133/2021','503','Licitações — estudo atualizado pela Lei nº 14.133/2021','Princípios, fases, modalidades, critérios de julgamento, contratação direta, desempate, margem de preferência e registro de preços.','## Atenção à vigência

Os PDFs enviados mencionam a Lei nº 8.666/1993. Ela está **revogada para novas licitações** desde o fim do regime de transição. O estudo atual deve usar a **Lei nº 14.133/2021**, que é a referência principal.

A Lei 14.133 prevê planejamento, fase preparatória, divulgação do edital, apresentação de propostas, julgamento, habilitação, recursos e homologação. Modalidades: concorrência, concurso, leilão, pregão e diálogo competitivo. O critério depende do objeto: menor preço, maior desconto, melhor técnica ou conteúdo artístico, técnica e preço, maior lance e maior retorno econômico.

Contratação direta abrange dispensa e inexigibilidade; licitação dispensada é hipótese legal distinta. O sistema de registro de preços é procedimento auxiliar, não modalidade. Critérios de desempate e margem de preferência devem ser lidos na redação atual da Lei 14.133 e regulamentos aplicáveis.

> **Regra editorial:** referências à Lei 8.666 nos PDFs ficam como comparação histórica, nunca como regra vigente.','Concursos públicos — Direito Administrativo','503','Conteúdo consolidado dos PDFs enviados pelo usuário em 28/10/2026, com revisão de vigência e remoção de marcas autorais.','[{"title": "Material enviado pelo usuário — 04-01_AlfaCon--licitacao-regime-juridico-prerrogativas-e-sujeicoes-competencia-legislativa-principios-lei-n-8-666-96.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 04-02_AlfaCon--licitacao-principios-da-vinculacao-ao-instrumento-de-convocacao-alteracao-superveniente-do-edital-principio-da-ad.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 04-03_AlfaCon--licitacao-conceito-e-objetivos-e-disposicoes-constitucionais-artigos-37-173-e-175-da-cf.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 04-04_AlfaCon--licitacao-criterios-de-desempate-e-margem-de-preferencia.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 05-01_AlfaCon--licitacao-modalidades-gerais.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 05-02_AlfaCon--licitacao-modalidades-especificas.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 05-03_AlfaCon--licitacao-licitacao-sistema-de-registro-de-precos-parte-1-hipoteses-de-contratacao-direta-licitacao-dispensada-li.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]','[{"f": "Qual é o ponto de atualização desta trilha?", "b": "Princípios, fases, modalidades, critérios de julgamento, contratação direta, desempate, margem de preferência e registro de preços."}]','[{"q": "As referências à Lei 8.666/1993 devem ser usadas como regra vigente para novas licitações.", "a": false, "why": "A referência atual é a Lei 14.133/2021; a Lei 8.666 é histórica para novas licitações."}]','active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('administrativo-acervo-lei-9784','Direito Administrativo','Processo administrativo','504','Processo administrativo federal — Lei nº 9.784/1999','Princípios, competência, impedimento, suspeição, direitos do administrado, instrução, decisão, motivação, recursos, anulação e revisão.','## Conteúdo atualizado

A Lei nº 9.784/1999 regula o processo administrativo no âmbito federal. Princípios expressos incluem legalidade, finalidade, motivação, razoabilidade, proporcionalidade, moralidade, ampla defesa, contraditório, segurança jurídica, interesse público e eficiência.

Estude competência, delegação e avocação; impedimento e suspeição; intimação; instrução; dever de decidir; motivação; recurso administrativo; revisão; anulação e revogação. A Administração tem prazo legal para decidir após concluída a instrução, e a motivação deve indicar fatos e fundamentos jurídicos.

> **Cai em prova:** delegação não transfere a titularidade da competência; avocação é excepcional, temporária e justificada.','Concursos públicos — Direito Administrativo','504','Conteúdo consolidado dos PDFs enviados pelo usuário em 28/10/2026, com revisão de vigência e remoção de marcas autorais.','[{"title": "Material enviado pelo usuário — Lei 9784 Atualizada e Esquematizada.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]','[{"f": "Qual é o ponto de atualização desta trilha?", "b": "Princípios, competência, impedimento, suspeição, direitos do administrado, instrução, decisão, motivação, recursos, anulação e revisão."}]','[{"q": "O conteúdo desta trilha foi organizado a partir dos materiais enviados e revisado para a legislação vigente.", "a": true, "why": "A trilha recebeu revisão editorial e jurídica."}]','active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('administrativo-acervo-responsabilidade','Direito Administrativo','Responsabilidade civil do Estado','505','Responsabilidade civil do Estado — art. 37, § 6º, da Constituição','Responsabilidade objetiva, risco administrativo, ação regressiva, omissões, agentes públicos e excludentes.','## Conteúdo atualizado

A Constituição adota responsabilidade objetiva das pessoas jurídicas de direito público e das pessoas jurídicas de direito privado prestadoras de serviço público pelos danos que seus agentes causarem a terceiros, nessa qualidade. Exige dano, conduta administrativa e nexo causal; não exige prova de culpa da vítima para indenização.

O Estado pode exercer ação regressiva contra o agente quando demonstrados dolo ou culpa. O risco administrativo admite excludentes ou atenuantes, como culpa exclusiva da vítima, fato exclusivo de terceiro e caso fortuito ou força maior quando rompem o nexo. O tratamento das omissões depende da natureza do dever estatal e da jurisprudência aplicável; não generalize a responsabilidade objetiva para toda omissão.

> **Cai em prova:** responsabilidade objetiva do Estado não significa responsabilidade integral.','Concursos públicos — Direito Administrativo','505','Conteúdo consolidado dos PDFs enviados pelo usuário em 28/10/2026, com revisão de vigência e remoção de marcas autorais.','[{"title": "Material enviado pelo usuário — 06-01_AlfaCon--parte-i-responsabilidade-civil-do-estado-responsabilidade-civil-do-estado-no-direito-brasileiro-responsabilidade-.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 06-02_AlfaCon--parte-ii-responsabilidade-civil-do-estado-responsabilidade-civil-do-estado-no-direito-brasileiro-responsabilidade.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]','[{"f": "Qual é o ponto de atualização desta trilha?", "b": "Responsabilidade objetiva, risco administrativo, ação regressiva, omissões, agentes públicos e excludentes."}]','[{"q": "O conteúdo desta trilha foi organizado a partir dos materiais enviados e revisado para a legislação vigente.", "a": true, "why": "A trilha recebeu revisão editorial e jurídica."}]','active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
insert into public.study_materials (slug,discipline,topic_label,sort_order,title,summary,body_md,contest_name,syllabus_topic_order,source_note,legal_basis,flashcards,quiz,content_status,reviewed_by,reviewed_at,law_version_checked_at) values ('administrativo-acervo-atos','Direito Administrativo','Atos administrativos','506','Atos administrativos — elementos, atributos, espécies e extinção','Competência, finalidade, forma, motivo, objeto, presunção, imperatividade, autoexecutoriedade, tipicidade, invalidação, convalidação e extinção.','## Conteúdo atualizado

Os elementos do ato são competência, finalidade, forma, motivo e objeto. Atributos frequentes: presunção de legitimidade e veracidade, imperatividade, autoexecutoriedade quando admitida e tipicidade.

Diferencie ato vinculado de discricionário; ato simples, complexo e composto; licença, autorização, permissão, homologação, aprovação e parecer. Ato ilegal pode ser anulado; ato válido pode ser revogado nos limites do mérito; vício sanável pode admitir convalidação quando não houver lesão ao interesse público ou prejuízo a terceiros.

> **Cai em prova:** motivo é a situação de fato e de direito; motivação é a explicação formal desses motivos.','Concursos públicos — Direito Administrativo','506','Conteúdo consolidado dos PDFs enviados pelo usuário em 28/10/2026, com revisão de vigência e remoção de marcas autorais.','[{"title": "Material enviado pelo usuário — 06-03_AlfaCon--atos-administrativos-parte-i-teoria-dos-atos-conceitos-classificacao-especies-elementos-requisitos-e-atributos-do.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 06-04_AlfaCon--atos-administrativos-parte-ii-teoria-dos-atos-conceitos-classificacao-especies-elementos-requisitos-e-atributos-d.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}, {"title": "Material enviado pelo usuário — 06-05_AlfaCon--atos-administrativos-parte-iii-teoria-dos-atos-conceitos-classificacao-especies-elementos-requisitos-e-atributos-.pdf", "url": "https://norteconcursos.xyz/dashboard/library"}]','[{"f": "Qual é o ponto de atualização desta trilha?", "b": "Competência, finalidade, forma, motivo, objeto, presunção, imperatividade, autoexecutoriedade, tipicidade, invalidação, convalidação e extinção."}]','[{"q": "O conteúdo desta trilha foi organizado a partir dos materiais enviados e revisado para a legislação vigente.", "a": true, "why": "A trilha recebeu revisão editorial e jurídica."}]','active','3ec587f5-0bf5-458d-841e-a19ff9ebbbf6',now(),now()) on conflict (slug) do update set title=excluded.title,summary=excluded.summary,body_md=excluded.body_md,source_note=excluded.source_note,legal_basis=excluded.legal_basis,flashcards=excluded.flashcards,quiz=excluded.quiz,updated_at=now();
